    # Returns list of basis vectors (length n) spanning nullspace of A (m x n)
    R, pivots = _rref_gf2(A)
    pivot_set = set(pivots)
    free_cols = [c for c in range(n) if c not in pivot_set]
    basis = []
    m = R.shape[0]
    for f in free_cols:
        x = np.zeros(n, dtype=np.uint8)
        x[f] = 1
        # for each pivot row i, pivot col p = pivots[i]
