    if not basis:
        return [np.zeros(8, dtype=np.uint8)]
    k = len(basis)
    out = []
    for mask in range(1 << k):
        v = np.zeros(8, dtype=np.uint8)
        for i in range(k):
            if (mask >> i) & 1:
                v ^= basis[i]
        out.append(v)
    return out

