    # return string s[0]..s[7] as usual binary with bit0 first? We'll output msb..lsb (qubit7..0) common.
    # Use conventional representation with highest index first (q7..q0)
    bits = [str(int(v[i])) for i in range(8)]
    # bits[i] corresponds to qubit i; output as q7...q0
    return "".join(bits[::-1])

