    # Use many shots; each shot gives a random y such that y·s=0 for s in {s1 or s2}
    shots = 20000
    tcirc = transpile(circuit, aer_sim, optimization_level=0)
    result = aer_sim.run(tcirc, shots=shots).result()
    counts = result.get_counts(tcirc)

    # Collect sampled y vectors, ignoring all-zero (uninformative)
    Ys = []
    for bs, ct in counts.items():
        v = _bitstring_to_vec(bs, 8)
        if np.all(v == 0):
            continue
        # add with multiplicity (cap to keep runtime bounded)
        rep = min(ct, 50)
        for _ in range(rep):
            Ys.append(v)
    if len(Ys) < 16:
        # fall back: still attempt with whatever we have
        for bs, ct in counts.items():
            v = _bitstring_to_vec(bs, 8)
            if np.all(v == 0):
                continue
            Ys.append(v)

    Y = np.array(Ys, dtype=np.uint8)
    # We'll search for two nonzero secrets s1,s2 such that for every y in sample: y·s1==0 OR y·s2==0.
    # Candidate set: all nonzero vectors in span of nullspace of some subset constraints.
    # Pragmatic approach: build candidate secrets from nullspace of random subsets and score them.

    rng = np.random.default_rng(12345)

    def dot_mod2(y, s):
        return int(np.bitwise_and(y, s).sum() & 1)

    # Precompute unique y's (for speed) with weights
    unique = {}
    for bs, ct in counts.items():
        v = _bitstring_to_vec(bs, 8)
        if np.all(v == 0):
            continue
        unique[tuple(v.tolist())] = unique.get(tuple(v.tolist()), 0) + ct
    y_list = [np.array(k, dtype=np.uint8) for k in unique.keys()]
    w_list = [unique[tuple(y.tolist())] for y in y_list]

    # Generate candidate secrets by taking nullspace of subsets of constraints
    candidates = set()
    m = len(y_list)
    idxs = np.arange(m)

    def add_from_subset(sub_idx):
        A = np.array([y_list[i] for i in sub_idx], dtype=np.uint8)
        basis = _nullspace_basis_gf2(A, 8)
        if len(basis) == 0:
            return
        # Enumerate all in span if small; otherwise sample
        if len(basis) <= 8:
            vecs = _span_all(basis)
            for v in vecs:
                if np.any(v):
                    candidates.add(tuple(v.tolist()))
        else:
            for _ in range(128):
                v = np.zeros(8, dtype=np.uint8)
                for b in basis:
                    if rng.integers(2):
                        v ^= b
                if np.any(v):
                    candidates.add(tuple(v.tolist()))

    # Deterministic subsets: first k y's increasing
    for k in (4, 5, 6, 7, 8, 10, 12):
        if m >= k:
            add_from_subset(list(range(k)))
    # Random subsets
    for _ in range(80):
        k = int(rng.integers(4, min(12, m) + 1)) if m >= 4 else m
        if k <= 0:
            continue
        sub = rng.choice(idxs, size=k, replace=False).tolist()
        add_from_subset(sub)

    # Ensure we have some candidates; if not, brute force all nonzero
    if not candidates:
        for val in range(1, 1 << 8):
            v = np.array([(val >> i) & 1 for i in range(8)], dtype=np.uint8)
            candidates.add(tuple(v.tolist()))

    cand_vecs = [np.array(t, dtype=np.uint8) for t in candidates]

    # Score candidate pair (s1,s2) by weighted satisfaction: for each y, satisfied if y·s1==0 or y·s2==0
    # Also require s1!=s2 and nonzero.
    best = None
    best_score = -1

    # Precompute dot table for speed
    dots = np.zeros((len(y_list), len(cand_vecs)), dtype=np.uint8)
    for i, y in enumerate(y_list):
        for j, s in enumerate(cand_vecs):
            dots[i, j] = dot_mod2(y, s)

    weights = np.array(w_list, dtype=np.int64)

    L = len(cand_vecs)
    # Limit candidates for pair search by individual score: y·s==0 frequency should be ~0.75 overall for true s
    indiv = []
    for j in range(L):
        ok = (dots[:, j] == 0).astype(np.int64)
        score = int((ok * weights).sum())
        indiv.append((score, j))
    indiv.sort(reverse=True)
    top = [j for _, j in indiv[:min(80, L)]]

    for a_i in range(len(top)):
        j1 = top[a_i]
        s1 = cand_vecs[j1]
        if not np.any(s1):
            continue
        for a_j in range(a_i + 1, len(top)):
            j2 = top[a_j]
            s2 = cand_vecs[j2]
            if not np.any(s2):
                continue
            if np.array_equal(s1, s2):
                continue
            sat = ((dots[:, j1] == 0) | (dots[:, j2] == 0)).astype(np.int64)
            score = int((sat * weights).sum())
            if score > best_score:
                best_score = score
                best = (s1.copy(), s2.copy())

    # Fallback: brute force second from top list against best first
    if best is None:
        # pick top two nonzero distinct
        nonzero = [cand_vecs[j] for j in top if np.any(cand_vecs[j])]
        if len(nonzero) >= 2:
            best = (nonzero[0], nonzero[1])
        else:
            best = (np.array([1,0,0,0,0,0,0,0], dtype=np.uint8),
                    np.array([0,1,0,0,0,0,0,0], dtype=np.uint8))

    s1, s2 = best

    # Canonicalize ordering by integer value
    def vec_to_int(v):
        val = 0
        for i in range(8):
            val |= (int(v[i]) << i)
        return val

    if vec_to_int(s2) < vec_to_int(s1):
        s1, s2 = s2, s1

    prediction1 = _vec_to_bitstring(s1)
    prediction2 = _vec_to_bitstring(s2)
    return prediction1, prediction2
"""
